import time

class RateLimitedClient:
    def __init__(self):
        self.limit = None
        self.remaining = None
        self.reset = None

    def handle_response(self, response):
        self.limit = int(response.headers.get('X-RateLimit-Limit', 100))
        self.remaining = int(response.headers.get('X-RateLimit-Remaining', 100))
        self.reset = int(response.headers.get('X-RateLimit-Reset', 0))

        if response.status_code == 429:
            retry_after = int(response.headers.get('Retry-After', 1))
            time.sleep(retry_after)
            return self.retry(response.request)

        if self.remaining < 10:
            # Back off proactively
            wait_time = max(0, self.reset - time.time())
            time.sleep(wait_time / self.remaining)

        return response

    def retry(self, request):
        return self.send(request)  # Retry once
